<script setup lang="ts">
import {ref,computed} from 'vue';import {useCoffee} from '../stores/coffee';import {money,localDate,dailyReport,csvCell} from '../../../../packages/shared/src/domain';import Icon from '../components/Icon.vue';
const s=useCoffee();const today=localDate();const start=ref(today);const end=ref(today);const branch=ref('all');const mode=ref('sales');const tab=ref('overview');
const ids=computed(()=>s.state.branches.filter(b=>branch.value==='all'||b.id===branch.value).map(b=>b.id));const orders=computed(()=>s.state.orders.filter(o=>ids.value.includes(o.branchId)&&localDate(o.createdAt)>=start.value&&localDate(o.createdAt)<=end.value));const tx=computed(()=>s.state.transactions.filter(t=>ids.value.includes(t.branchId)&&localDate(t.at)>=start.value&&localDate(t.at)<=end.value));const completed=computed(()=>orders.value.filter(o=>!['pending','cancelled'].includes(o.state)));const gross=computed(()=>completed.value.reduce((n,o)=>n+o.lines.reduce((a,l)=>a+l.total,0),0));const discounts=computed(()=>completed.value.reduce((n,o)=>n+o.discount,0));const surcharges=computed(()=>completed.value.reduce((n,o)=>n+o.surcharge,0));const collections=computed(()=>tx.value.filter(t=>t.kind==='collection').reduce((n,t)=>n+t.amount,0));const refunds=computed(()=>tx.value.filter(t=>t.kind==='refund').reduce((n,t)=>n+t.amount,0));const sold=computed(()=>{const map=new Map<string,{name:string;qty:number;total:number}>();for(const o of completed.value)for(const l of o.lines){const row=map.get(l.productId)??{name:l.name,qty:0,total:0};row.qty+=l.quantity;row.total+=l.total;map.set(l.productId,row)}return [...map.values()].sort((a,b)=>b.qty-a.qty)});
function exportReport(){const data=tab.value==='items'?[['Món','Số lượng','Doanh thu'],...sold.value.map(r=>[r.name,r.qty,r.total])]:[['Mã đơn','Cơ sở','Ngày','Tổng tiền','Đã thu','Trạng thái'],...orders.value.map(o=>[o.number,s.state.branches.find(b=>b.id===o.branchId)?.name??'',localDate(o.createdAt),o.total,o.paid,o.state])];const blob=new Blob(['\uFEFF'+data.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='bao-cao-'+start.value+'-'+end.value+'.csv';a.click();URL.revokeObjectURL(url)}
</script><template><div class="page"><div class="page-heading"><div><h2>Báo cáo & đối soát</h2><p>Phân biệt doanh thu bán hàng và dòng tiền thực thu.</p></div><button class="btn outline" @click="exportReport"><Icon name="download"/>Xuất CSV cho Excel</button></div><div class="panel report-filters"><label class="field"><span>Từ ngày</span><input type="date" v-model="start" aria-label="Từ ngày"></label><label class="field"><span>Đến ngày</span><input type="date" v-model="end" :min="start" aria-label="Đến ngày"></label><label class="field"><span>Cơ sở</span><select v-model="branch"><option value="all">Tất cả cơ sở</option><option v-for="b in s.state.branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><p v-if="end<start" class="inline-error">Ngày kết thúc cần sau ngày bắt đầu.</p></div><div class="document-tabs report-tabs"><button v-for="(name,key) in {overview:'Đối soát',items:'Món bán chạy',payments:'Thanh toán',refunds:'Hoàn tiền',branches:'Theo cơ sở',shifts:'Theo ca',invoices:'Hóa đơn điện tử'}" :key="key" :class="{selected:tab===key}" @click="tab=key">{{name}}</button></div><section v-if="tab==='overview'" class="report-overview"><article class="panel reconciliation"><h3>Đối soát doanh thu</h3><div class="total-row"><span>Tổng giá trị món bán</span><b>{{money(gross)}}</b></div><div class="total-row"><span>− Giảm giá</span><b>{{money(discounts)}}</b></div><div class="total-row"><span>+ Phụ thu</span><b>{{money(surcharges)}}</b></div><div class="total-row"><span>− Hoàn tiền trong kỳ</span><b>{{money(refunds)}}</b></div><div class="total-row grand-total"><strong>Doanh thu thuần theo kỳ</strong><strong>{{money(gross-discounts+surcharges-refunds)}}</strong></div><p class="muted small-copy">Đơn theo ngày tạo; hoàn tiền theo ngày ghi nhận. Quy tắc kế toán sẽ được chốt khi triển khai backend.</p></article><article class="panel reconciliation"><h3>Dòng tiền & công nợ</h3><div class="total-row"><span>Tiền đã thu trong kỳ</span><b>{{money(collections)}}</b></div><div class="total-row"><span>Tiền hoàn trong kỳ</span><b>{{money(refunds)}}</b></div><div class="total-row grand-total"><strong>Tiền thực thu</strong><strong>{{money(collections-refunds)}}</strong></div><div class="total-row"><span>Chưa thu của đơn trong kỳ</span><b class="amber">{{money(completed.reduce((n,o)=>n+Math.max(0,o.total-o.paid),0))}}</b></div><div class="report-counts"><div><strong>{{orders.length}}</strong><span>Tổng đơn</span></div><div><strong>{{orders.filter(o=>o.state==='cancelled').length}}</strong><span>Đơn hủy</span></div></div></article></section><section v-else-if="tab==='items'" class="panel table-scroll"><table class="data-table"><thead><tr><th>Món</th><th>Số lượng bán</th><th>Giá trị món</th></tr></thead><tbody><tr v-for="r in sold" :key="r.name"><td>{{r.name}}</td><td>{{r.qty}}</td><td class="numeric">{{money(r.total)}}</td></tr></tbody></table><div v-if="!sold.length" class="empty">Chưa có món bán trong kỳ.</div></section><section v-else-if="['payments','refunds'].includes(tab)" class="panel table-scroll"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Cơ sở</th><th>Ngày ghi nhận</th><th>Phương thức</th><th>Số tiền</th><th>Tham chiếu</th></tr></thead><tbody><tr v-for="t in tx.filter(t=>tab==='refunds'?t.kind==='refund':t.kind==='collection')" :key="t.id"><td>{{s.state.orders.find(o=>o.id===t.orderId)?.number}}</td><td>{{s.state.branches.find(b=>b.id===t.branchId)?.name}}</td><td>{{localDate(t.at)}}</td><td>{{t.method==='cash'?'Tiền mặt':'Chuyển khoản'}}</td><td class="numeric">{{money(t.amount)}}</td><td>{{t.reference}}</td></tr></tbody></table><div v-if="!tx.some(t=>tab==='refunds'?t.kind==='refund':t.kind==='collection')" class="empty">Chưa có giao dịch trong kỳ.</div></section><section v-else-if="tab==='branches'" class="panel table-scroll"><table class="data-table"><thead><tr><th>Cơ sở</th><th>Doanh thu bán</th><th>Thực thu</th><th>Hoàn tiền</th></tr></thead><tbody><tr v-for="id in ids" :key="id"><td>{{s.state.branches.find(b=>b.id===id)?.name}}</td><td class="numeric">{{money(completed.filter(o=>o.branchId===id).reduce((n,o)=>n+o.total,0))}}</td><td class="numeric">{{money(tx.filter(t=>t.branchId===id).reduce((n,t)=>n+(t.kind==='refund'?-t.amount:t.amount),0))}}</td><td class="numeric">{{money(tx.filter(t=>t.branchId===id&&t.kind==='refund').reduce((n,t)=>n+t.amount,0))}}</td></tr></tbody></table></section><section v-else class="panel empty"><Icon :name="tab==='shifts'?'clock':'file'" :size="40"/><h3>{{tab==='shifts'?'Chưa có dữ liệu ca làm việc':'Chưa có hóa đơn điện tử'}}</h3><p>{{tab==='shifts'?'Đối soát ca và nhân viên cần dữ liệu phiên làm việc từ API.':'Cần kết nối nhà cung cấp để tra cứu hóa đơn đã phát hành.'}}</p><RouterLink v-if="tab==='invoices'" to="/admin/invoices" class="btn outline">Cài đặt hóa đơn điện tử</RouterLink></section></div></template>
